{
  "validations": [
    {
      "case": 1,
      "claim": "One of the main components of Media Store is a server-side web front end, namely the Facade component, which delivers websites to the users and provides session management.",
      "approve": true
    },
    {
      "case": 2,
      "claim": "To this end, the Facade component delivers the corresponding registration and log-in pages to users.",
      "approve": true
    },
    {
      "case": 3,
      "claim": "In addition, users can browse, download, and upload audio files using the Facade component.",
      "approve": true
    },
    {
      "case": 4,
      "claim": "Application business logic is provided by a central business logic component, called the MediaManagement component.",
      "approve": true
    },
    {
      "case": 5,
      "claim": "The MediaManagement component coordinates the communication of other components.",
      "approve": true
    },
    {
      "case": 6,
      "claim": "The UserManagement component answers the requests for registration and authentication.",
      "approve": true
    },
    {
      "case": 7,
      "claim": "The UserDBAdapter component queries the database.",
      "approve": true
    },
    {
      "case": 8,
      "claim": "When a user logs into the system, Media Store does not store the password in plain text, but rather the UserManagement component implements further functions to hash and salt the passwords.",
      "approve": true
    },
    {
      "case": 9,
      "claim": "To this end, the requested files are first reencoded.",
      "approve": true
    },
    {
      "case": 10,
      "claim": "The re-encoded files are then digitally and individually watermarked by the TagWatermarking component.",
      "approve": true
    },
    {
      "case": 11,
      "claim": "Afterward, the MediaManagement component forwards these audio files from the TagWatermarking component to the user.",
      "approve": true
    },
    {
      "case": 12,
      "claim": "To allow users to download several files at a time, we provide the Packaging component, which archives multiple audio files into a single compressed file.",
      "approve": true
    },
    {
      "case": 13,
      "claim": "The ReEncoder component converts the bit rates of audio files.",
      "approve": true
    },
    {
      "case": 14,
      "claim": "The persistence tier contains components that are concerned with the storage of audio files and their meta-data.",
      "approve": true
    },
    {
      "case": 15,
      "claim": "The Database component represents an actual database (e.g., MySQL).",
      "approve": true
    },
    {
      "case": 16,
      "claim": "It stores user information and meta-data of audio files such as the name and the genre.",
      "approve": true
    },
    {
      "case": 17,
      "claim": "After the user calls the page to list all available audio files, AudioAccess creates a query that is sent to the Database component.",
      "approve": false
    },
    {
      "case": 18,
      "claim": "After the user calls the page to list all available audio files, AudioAccess creates a query that is sent to the Database component.",
      "approve": true
    },
    {
      "case": 19,
      "claim": "When a user uploads an audio file, the MediaAccess component stores it at the predefined location.",
      "approve": true
    },
    {
      "case": 20,
      "claim": "The MediaAccess component encapsulates database access for meta-data of audio files.",
      "approve": true
    },
    {
      "case": 21,
      "claim": "By contrast, the UserDBAdapter component provides all functions required in order to encapsulate database access for the user data.",
      "approve": true
    },
    {
      "case": 22,
      "claim": "The UserDBAdapter component creates a query based on the user's request.",
      "approve": true
    },
    {
      "case": 23,
      "claim": "The Database component then executes the actual query for files.",
      "approve": true
    },
    {
      "case": 24,
      "claim": "All salted hashes of passwords are also stored in the Database component.",
      "approve": true
    },
    {
      "case": 25,
      "claim": "When a user requests files to download, the MediaAccess component fetches the associated meta-data from the Database.",
      "approve": true
    }
  ]
}

